{
  "project_id": "checkout",
  "header": {
    "owner": {"role": "pm", "person": "olena.k"},
    "version": "1.4.0",
    "last_reviewed": "2026-05-10",
    "reporting_cadence_days": 7
  },
  "signals": [
    {
      "signal_id": "schedule_variance_pct",
      "unit": "percent",
      "input_source": {"system": "PM", "query": "PM estimate at the weekly sync"},
      "comparator": "gt",
      "amber_threshold": "significant",
      "red_threshold": 20,
      "evidence": ["TBD"]
    },
    {
      "signal_id": "test_coverage_pct",
      "unit": "percent",
      "input_source": {"system": "SonarQube", "query": "project CHK measure coverage"},
      "comparator": "lt",
      "amber_threshold": 60,
      "red_threshold": 70,
      "evidence": ["policy://eng/coverage-floor"]
    }
  ],
  "actions": {
    "green": "continue normal cadence",
    "amber": {"step": "discuss at the next sync", "deadline_hours": 72},
    "red": {"playbook": "distressed-project-rescue", "first_step": "sponsor notified and rescue playbook opened", "within_hours": 4, "fires_at": "next_sync"}
  },
  "review_log": [
    {
      "logged_at": "2026-05-25",
      "kind": "override",
      "person": "olena.k",
      "cycle_date": "2026-05-25",
      "computed_colour": "red",
      "reported_colour": "amber",
      "reason": "steering committee is on Thursday; the team is confident the slip recovers"
    }
  ],
  "colour_history": [
    {
      "computed_at": "2026-05-25",
      "policy_version": "1.4.0",
      "policy_last_reviewed": "2026-05-10",
      "values": [
        {"signal_id": "schedule_variance_pct", "value": 22},
        {"signal_id": "test_coverage_pct", "value": 80}
      ],
      "computed_colour": "amber",
      "reported_colour": "amber"
    }
  ]
}
